    private function subscriptions(string $method): never
    {
        $tenants=Store::all('SELECT pt.product_tenant_guid,CONCAT(o.display_name," — ",p.name) label,pt.product_guid FROM product_tenants pt JOIN organisations o ON o.organisation_guid=pt.organisation_guid JOIN products p ON p.product_guid=pt.product_guid WHERE pt.status="ACTIVE" ORDER BY o.display_name');$plans=Store::all('SELECT pl.plan_guid,pl.product_guid,CONCAT(p.name," — ",pl.name) label FROM plans pl JOIN products p ON p.product_guid=pl.product_guid WHERE pl.status="ACTIVE" ORDER BY p.name,pl.name');
        if($method==='POST'){$tenant=null;foreach($tenants as$t)if($t['product_tenant_guid']===$_POST['product_tenant_guid'])$tenant=$t;$plan=null;foreach($plans as$p)if($p['plan_guid']===$_POST['plan_guid'])$plan=$p;if(!$tenant||!$plan||$tenant['product_guid']!==$plan['product_guid'])throw new \RuntimeException('Plan does not belong to tenant product');$guid=Uuid::v7();Store::exec('INSERT INTO subscriptions(subscription_guid,product_tenant_guid,plan_guid,status,billing_state,service_access_state,current_period_start,current_period_end,created_at,updated_at) VALUES(?,?,?,"ACTIVE","ACTIVE","FULL",NOW(6),DATE_ADD(NOW(6),INTERVAL 1 MONTH),NOW(6),NOW(6))',[Uuid::toBinary($guid),Uuid::toBinary($tenant['product_tenant_guid']),Uuid::toBinary($plan['plan_guid'])]);RedisStore::del('entitlements:'.$tenant['product_tenant_guid']);Audit::log('subscription.create','subscription',$guid);View::flash('Subscription activated.');Http::redirect('/admin/subscriptions');}
        $items=Store::all('SELECT s.subscription_guid,s.status,s.billing_state,s.service_access_state,s.current_period_end,pt.display_name tenant,pl.name plan,p.name product FROM subscriptions s JOIN product_tenants pt ON pt.product_tenant_guid=s.product_tenant_guid JOIN plans pl ON pl.plan_guid=s.plan_guid JOIN products p ON p.product_guid=pt.product_guid ORDER BY s.created_at DESC');$rows=[];foreach($items as$r)$rows[]=[$this->e($r['tenant']),$this->e($r['product']),$this->e($r['plan']),$this->status($r['status']),$this->e($r['service_access_state']),$this->e($r['current_period_end']),'<code>'.$this->e($r['subscription_guid']).'</code>','<a class="button small" href="/admin/subscriptions/'.$this->e($r['subscription_guid']).'/edit">Edit</a>'];$form='<section class="card"><h2>Activate subscription</h2><form method="post" class="form-grid">'.$this->csrf().'<label>Product tenant'.$this->select('product_tenant_guid',$tenants,'product_tenant_guid','label').'</label><label>Plan'.$this->select('plan_guid',$plans,'plan_guid','label').'</label><div class="form-action"><button class="primary">Activate</button></div></form></section>';View::layout('Subscriptions',$form.'<section class="card"><h2>Subscriptions</h2>'.$this->table(['Tenant','Product','Plan','Status','Access','Period End','GUID','Actions'],$rows).'</section>');
    }

    private function billing(string $method): never
    {
        $tenants=Store::all('SELECT pt.product_tenant_guid,CONCAT(o.display_name," — ",p.name) label FROM product_tenants pt JOIN organisations o ON o.organisation_guid=pt.organisation_guid JOIN products p ON p.product_guid=pt.product_guid WHERE pt.status="ACTIVE" ORDER BY o.display_name');if($method==='POST'){$tenant=$_POST['product_tenant_guid'];$amount=(int)round(((float)($_POST['amount']??0))*100);$invGuid=Uuid::v7();$num='DGT-'.gmdate('Ymd').'-'.strtoupper(substr(str_replace('-','',$invGuid),-8));Store::tx(function()use($tenant,$amount,$invGuid,$num){Store::exec('INSERT INTO invoices(invoice_guid,product_tenant_guid,invoice_number,currency,subtotal_minor,total_minor,status,due_at,created_at,updated_at) VALUES(?,?,?,"INR",?,?,"OPEN",DATE_ADD(NOW(),INTERVAL 7 DAY),NOW(6),NOW(6))',[Uuid::toBinary($invGuid),Uuid::toBinary($tenant),$num,$amount,$amount]);Store::exec('INSERT INTO invoice_items(invoice_item_guid,invoice_guid,description,quantity,unit_amount_minor,line_total_minor) VALUES(?,?,"Platform subscription",1,?,?)',[Uuid::toBinary(Uuid::v7()),Uuid::toBinary($invGuid),$amount,$amount]);});Audit::log('invoice.create','invoice',$invGuid);View::flash('Invoice created: '.$num);Http::redirect('/admin/billing');}
        $invoices=Store::all('SELECT i.invoice_guid,i.invoice_number,i.currency,i.total_minor,i.status,i.due_at,pt.display_name tenant FROM invoices i JOIN product_tenants pt ON pt.product_tenant_guid=i.product_tenant_guid ORDER BY i.created_at DESC LIMIT 100');$rows=[];foreach($invoices as$i){$action=in_array($i['status'],['DRAFT','OPEN'],true)?'<form class="inline-form" method="post" action="/admin/billing/invoices/'.$this->e($i['invoice_guid']).'/void">'.$this->csrf().'<button class="small danger">Void</button></form>':'—';$rows[]=[$this->e($i['invoice_number']),$this->e($i['tenant']),$this->money($i['total_minor'],$i['currency']),$this->status($i['status']),$this->e($i['due_at']),'<code>'.$this->e($i['invoice_guid']).'</code>',$action];}$payments=Store::all('SELECT pay.provider,pay.amount_minor,pay.currency,pay.status,pay.provider_reference,pt.display_name tenant,pay.created_at FROM payments pay JOIN product_tenants pt ON pt.product_tenant_guid=pay.product_tenant_guid ORDER BY pay.created_at DESC LIMIT 50');$prows=[];foreach($payments as$p)$prows[]=[$this->e($p['tenant']),$this->e($p['provider']),$this->money($p['amount_minor'],$p['currency']),$this->status($p['status']),$this->e($p['provider_reference']??'—'),$this->e($p['created_at'])];$form='<section class="card"><h2>Create invoice</h2><form method="post" class="form-grid">'.$this->csrf().'<label>Tenant'.$this->select('product_tenant_guid',$tenants,'product_tenant_guid','label').'</label><label>Amount INR<input name="amount" type="number" step="0.01" min="0" required></label><div class="form-action"><button class="primary">Create invoice</button></div></form></section>';View::layout('Invoices & Payments',$form.'<section class="card"><h2>Invoices</h2>'.$this->table(['Invoice','Tenant','Total','Status','Due','GUID','Actions'],$rows).'</section><section class="card"><h2>Payments</h2>'.$this->table(['Tenant','Provider','Amount','Status','Reference','Created'],$prows).'</section>');
    }

    private function operations(): never
