    }

    private function healthData(): array
    {
        $db=['ok'=>false];try{$start=microtime(true);Store::value('SELECT 1');$db=['ok'=>true,'latency_ms'=>round((microtime(true)-$start)*1000,1)];}catch(\Throwable$e){$db=['ok'=>false,'error'=>$e->getMessage()];}
        $redis=['enabled'=>RedisStore::enabled(),'ok'=>false];if(RedisStore::enabled()){try{$start=microtime(true);$pong=RedisStore::client()?->ping();$redis=['enabled'=>true,'ok'=>(bool)$pong,'latency_ms'=>round((microtime(true)-$start)*1000,1)];}catch(\Throwable$e){$redis=['enabled'=>true,'ok'=>false,'error'=>$e->getMessage()];}}
        $worker=Store::one('SELECT received_at,status,version FROM application_heartbeats ORDER BY received_at DESC LIMIT 1');$queue=['queued'=>(int)Store::value('SELECT COUNT(*) FROM jobs WHERE status="QUEUED"'),'failed'=>(int)Store::value('SELECT COUNT(*) FROM jobs WHERE status="FAILED"'),'outbox'=>(int)Store::value('SELECT COUNT(*) FROM outbox_events WHERE status="PENDING"')];return ['ok'=>$db['ok']&&(!$redis['enabled']||$redis['ok']),'version'=>$this->version(),'environment'=>Config::get('app.env'),'database'=>$db,'redis'=>$redis,'queue'=>$queue,'latest_application_heartbeat'=>$worker,'request_guid'=>Http::requestGuid()];
    }
    private function healthReady(): never{$h=$this->healthData();Http::json($h,$h['ok']?200:503);}
    private function healthPage(): never{$h=$this->healthData();$body='<div class="health"><div class="health-row"><strong>Application</strong>'.$this->status('ONLINE').'<span>v'.$this->e($h['version']).'</span></div><div class="health-row"><strong>MariaDB</strong>'.$this->status($h['database']['ok']?'ONLINE':'FAILED').'<span>'.($h['database']['latency_ms']??'—').' ms</span></div><div class="health-row"><strong>Redis</strong>'.$this->status(!$h['redis']['enabled']?'DISABLED':($h['redis']['ok']?'ONLINE':'FAILED')).'<span>'.($h['redis']['latency_ms']??'—').' ms</span></div><div class="health-row"><strong>Queue</strong>'.$this->status($h['queue']['failed']?'DEGRADED':'ONLINE').'<span>'.$h['queue']['queued'].' queued · '.$h['queue']['outbox'].' outbox</span></div></div>';View::layout('System Health',$body,['subtitle'=>'Database, Redis, queues, application heartbeats and version']);}

    private function impersonation(string $method): never
    {
        $admin=Auth::requireAdmin();$members=Store::all('SELECT m.membership_guid,m.user_guid,m.organisation_guid,m.role_key,u.email,u.display_name user_name,o.display_name organisation FROM memberships m JOIN platform_users u ON u.user_guid=m.user_guid JOIN organisations o ON o.organisation_guid=m.organisation_guid WHERE m.status="ACTIVE" ORDER BY o.display_name,u.display_name');if($method==='POST'){$membership=null;foreach($members as$m)if($m['membership_guid']===$_POST['membership_guid'])$membership=$m;if(!$membership)throw new \RuntimeException('Membership not found');$reason=trim($_POST['reason']??'');if(strlen($reason)<8)throw new \RuntimeException('Support reason is required');$token='imp_'.rtrim(strtr(base64_encode(random_bytes(36)),'+/','-_'),'=');$guid=Uuid::v7();Store::exec('INSERT INTO impersonation_grants(impersonation_guid,admin_guid,organisation_guid,user_guid,token_hash,reason,created_at,expires_at) VALUES(?,?,?,?,?,?,NOW(6),DATE_ADD(NOW(6),INTERVAL 10 MINUTE))',[Uuid::toBinary($guid),Uuid::toBinary($admin['admin_guid']),Uuid::toBinary($membership['organisation_guid']),Uuid::toBinary($membership['user_guid']),hash('sha256',$token,true),$reason]);Audit::log('impersonation.create','impersonation_grant',$guid,'SUCCESS',['organisation_guid'=>$membership['organisation_guid'],'user_guid'=>$membership['user_guid'],'reason'=>$reason]);View::flash('ONE-TIME IMPERSONATION TOKEN — copy now: '.$token);Http::redirect('/admin/impersonation');}
        $rows=[];foreach($members as$m)$rows[]=[$this->e($m['organisation']),$this->e($m['user_name']),$this->e($m['email']),$this->e($m['role_key']),'<code>'.$this->e($m['membership_guid']).'</code>'];$options=[];foreach($members as$m)$options[]=['membership_guid'=>$m['membership_guid'],'label'=>$m['organisation'].' — '.$m['user_name'].' ('.$m['role_key'].')'];$body='<section class="card"><h2>Create support impersonation grant</h2><p class="muted">Tokens are one-time, tenant-bound, audited and expire after 10 minutes.</p><form method="post" class="form-grid">'.$this->csrf().'<label>Membership'.$this->select('membership_guid',$options,'membership_guid','label').'</label><label class="wide">Reason<input name="reason" minlength="8" required></label><div class="form-action"><button class="primary">Create one-time token</button></div></form></section><section class="card"><h2>Eligible memberships</h2>'.$this->table(['Organisation','User','Email','Role','Membership GUID'],$rows).'</section>';View::layout('Impersonation',$body,['subtitle'=>'Audited Platform support access']);
    }
    private function consumeImpersonation(): never
    {
        ServiceAuth::requireScope('impersonation.consume');$d=Http::bodyJson();$token=$d['token']??'';$tenantGuid=$d['product_tenant_guid']??'';$pt=Store::one('SELECT organisation_guid FROM product_tenants WHERE product_tenant_guid=? AND status="ACTIVE"',[Uuid::toBinary($tenantGuid)]);if(!$pt)Http::json(['ok'=>false,'code'=>'TENANT_NOT_FOUND'],404);$grant=Store::one('SELECT impersonation_guid,admin_guid,organisation_guid,user_guid,reason,expires_at,used_at,revoked_at FROM impersonation_grants WHERE token_hash=? LIMIT 1',[hash('sha256',$token,true)]);if(!$grant||$grant['used_at']||$grant['revoked_at']||strtotime($grant['expires_at'])<time()||$grant['organisation_guid']!==$pt['organisation_guid'])Http::json(['ok'=>false,'code'=>'IMPERSONATION_INVALID'],403);$membership=Store::one('SELECT membership_guid,organisation_guid,user_guid,role_key,status FROM memberships WHERE organisation_guid=? AND user_guid=? AND status="ACTIVE"',[Uuid::toBinary($grant['organisation_guid']),Uuid::toBinary($grant['user_guid'])]);if(!$membership)Http::json(['ok'=>false,'code'=>'MEMBERSHIP_NOT_ACTIVE'],403);Store::exec('UPDATE impersonation_grants SET used_at=NOW(6) WHERE impersonation_guid=?',[Uuid::toBinary($grant['impersonation_guid'])]);$user=Store::one('SELECT user_guid,email,display_name,status FROM platform_users WHERE user_guid=?',[Uuid::toBinary($grant['user_guid'])]);Audit::log('impersonation.consume','impersonation_grant',$grant['impersonation_guid'],'SUCCESS',['product_tenant_guid'=>$tenantGuid]);Http::json(['ok'=>true,'identity'=>['user'=>$user,'membership'=>$membership,'impersonator_admin_guid'=>$grant['admin_guid'],'reason'=>$grant['reason']]]);
    }

    private function adminSecurity(string $method): never
    {
        $admin=Auth::requireAdmin();$row=Store::one('SELECT admin_guid,email,display_name,password_hash,mfa_enabled,mfa_secret_enc FROM platform_admins WHERE admin_guid=?',[Uuid::toBinary($admin['admin_guid'])]);Auth::start();if(empty($_SESSION['_admin_mfa_setup']))$_SESSION['_admin_mfa_setup']=Mfa::secret();$secret=$_SESSION['_admin_mfa_setup'];$message='';
        if($method==='POST'){$action=$_POST['action']??'enable';if(!password_verify($_POST['password']??'',$row['password_hash']))throw new \RuntimeException('Current password verification failed');if($action==='enable'){if(!Mfa::verify($secret,$_POST['totp']??''))throw new \RuntimeException('Authenticator code is invalid');Store::exec('UPDATE platform_admins SET mfa_secret_enc=?,mfa_enabled=1,updated_at=NOW(6) WHERE admin_guid=?',[Crypto::encrypt($secret),Uuid::toBinary($admin['admin_guid'])]);unset($_SESSION['_admin_mfa_setup']);Audit::log('mfa.enable','platform_admin',$admin['admin_guid']);View::flash('MFA enabled for Platform Admin.');Http::redirect('/admin/security');}if($action==='disable'){if(empty($row['mfa_enabled']))throw new \RuntimeException('MFA is not enabled');$current=Crypto::decrypt($row['mfa_secret_enc']);if(!Mfa::verify($current,$_POST['totp']??''))throw new \RuntimeException('Authenticator code is invalid');Store::exec('UPDATE platform_admins SET mfa_secret_enc=NULL,mfa_enabled=0,updated_at=NOW(6) WHERE admin_guid=?',[Uuid::toBinary($admin['admin_guid'])]);Audit::log('mfa.disable','platform_admin',$admin['admin_guid']);View::flash('MFA disabled.');Http::redirect('/admin/security');}}
